import{_ as e,o as r,c as o,a5 as d}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"直接Reactive对象和复制一个对象","description":"下面用 一个极简可运行的小例子 带你完整走一遍 场景 代码 现象 执行时序 ❌ 错误写法 直接对 core.state 做 reactive example wrong.ts 视图 / watchEffect 不更新 ① Core 改“源对象” ② Vue 看不见 ③ Objec。","frontmatter":{"title":"直接Reactive对象和复制一个对象","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"下面用 一个极简可运行的小例子 带你完整走一遍 场景 代码 现象 执行时序 ❌ 错误写法 直接对 core.state 做 reactive example wrong.ts 视图 / watchEffect 不更新 ① Core 改“源对象” ② Vue 看不见 ③ Objec。","sidebarWeight":156,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/响应式问题/直接Reactive对象和复制一个对象.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/直接Reactive对象和复制一个对象.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/直接Reactive对象和复制一个对象.md"}'),s={name:"posts/Vue系统教程/03-响应式与组合式 API/直接Reactive对象和复制一个对象.md"};function n(a,t,c,g,u,i){return r(),o("div",null,[...t[0]||(t[0]=[d('<div><h1 id="直接reactive对象和复制一个对象" tabindex="-1">直接Reactive对象和复制一个对象 <a class="header-anchor" href="#直接reactive对象和复制一个对象" aria-label="Permalink to &quot;直接Reactive对象和复制一个对象&quot;">​</a></h1><blockquote><p>本节目标：理解“直接Reactive对象和复制一个对象”的核心思路，并能把它用于实际开发或面试表达。 下面用 <strong>一个极简可运行的小例子</strong> 带你完整走一遍</p></blockquote><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>场景</strong></td><td><strong>代码</strong></td><td><strong>现象</strong></td><td><strong>执行时序</strong></td></tr><tr><td>❌ <strong>错误写法</strong></td><td></td><td></td><td></td></tr><tr><td>直接对 core.state 做 reactive</td><td>example-wrong.ts</td><td>视图 / watchEffect 不更新</td><td>① Core 改“源对象”</td></tr><tr><td>② Vue <strong>看不见</strong></td><td></td><td></td><td></td></tr><tr><td>③ Object.assign 复制“相同值” → setter 不触发</td><td></td><td></td><td></td></tr><tr><td>✅ <strong>正确写法</strong></td><td></td><td></td><td></td></tr><tr><td>用 <strong>镜像对象</strong> + sync()</td><td>example-right.ts</td><td>每次输入 / 失焦立刻更新</td><td>① Core 改源对象</td></tr><tr><td>② sync() 把“新值”写进 Proxy → setter 触发</td><td></td><td></td><td></td></tr><tr><td>③ 视图 &amp; watch响应该变化</td><td></td><td></td><td></td></tr></tbody></table><p><strong>1. 准备一个「纯逻辑 Core」(core.ts)</strong> // core.ts —— 不依赖任何框架 export type CoreState = { formatted: string; counter: number } export function createCore(): { state: CoreState parseInput: (str: string) =&gt; void commit: () =&gt; void } { const state: CoreState = { formatted: &#39;100&#39;, counter: 0 } return { state, /** 用户每打一个字符 <em>/ parseInput(str) { state.formatted = str // ← 直接改原始对象 }, /</em>* 用户失焦 / 回车 */ commit() { const n = Number(state.formatted) state.formatted = Number.isNaN(n) ? &#39;–&#39; : n.toFixed(2) state.counter++ } } }</p><p><strong>2.</strong> <strong>❌</strong> <strong>错误写法：直接 reactive(core.state)</strong> // example-wrong.ts import { createApp, reactive, watchEffect } from &#39;vue&#39; import { createCore } from &#39;./core&#39; const core = createCore() const vueState = reactive(core.state) // 直接把原始对象做成 Proxy watchEffect(() =&gt; console.log(&#39;-&gt; watch&#39;, vueState.formatted)) const App = { template: <code> \\&lt;input :value=&quot;vueState.formatted&quot; @input=&quot;e =\\&gt; onInput(e.target.value)&quot; @blur=&quot;onBlur&quot; /\\&gt; \\&lt;p\\&gt;Counter: \\{\\{ vueState.counter \\}\\}\\&lt;/p\\&gt;</code>, setup() { const onInput = (v: string) =&gt; core.parseInput(v) // 改原始对象 const onBlur = () =&gt; core.commit() // 改原始对象 return { vueState, onInput, onBlur } } } createApp(App).mount(&#39;#app&#39;) &lt;img src=&quot;<a href="https://i.imgur.com/f2vNYnC.gif" target="_blank" rel="noreferrer">https://i.imgur.com/f2vNYnC.gif</a>&quot; width=&quot;390&quot; /&gt;</p><p><strong>现象</strong>：</p><ul><li>打字 &amp; 失焦后，&lt;p&gt; 与 watchEffect <strong>都不更新</strong>。</li></ul><p><strong>一步步发生了什么？</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>时刻</strong></td><td><strong>操作</strong></td><td><strong>发生的写入</strong></td><td><strong>Vue 是否拦截</strong></td></tr><tr><td>① 打字</td><td>core.parseInput(&#39;ccc&#39;)</td><td>core.state.formatted = &#39;ccc&#39;（改原始对象）</td><td>❌ Proxy 无感知</td></tr><tr><td>② 失焦</td><td>core.commit() 把 &#39;ccc&#39; → &#39;NaN&#39;</td><td>仍改原始对象</td><td>❌ Proxy 无感知</td></tr><tr><td>③ 你若调用 Object.assign(vueState, core.state)</td><td>把 &#39;NaN&#39; 复制给同名属性，但</td><td></td><td></td></tr><tr><td><strong>vueState.formatted 早就是 &#39;NaN&#39;</strong>（因它与原对象同址）</td><td>setter 比对旧值 === 新值 → <strong>不触发依赖</strong></td><td></td><td></td></tr></tbody></table><p><strong>3.</strong> <strong>✅</strong> <strong>正确写法：镜像 + sync()</strong> // example-right.ts import { createApp, reactive, watchEffect } from &#39;vue&#39; import { createCore } from &#39;./core&#39; const core = createCore() // 复制一份快照做响应式代理 const vueState = reactive({ ...core.state }) function sync() { // 把最新值写回 Proxy（Setter → 触发依赖） vueState.formatted = core.state.formatted vueState.counter = core.state.counter } watchEffect(() =&gt; console.log(&#39;-&gt; watch&#39;, vueState.formatted)) const App = { template: <code> \\&lt;input :value=&quot;vueState.formatted&quot; @input=&quot;e =\\&gt; onInput(e.target.value)&quot; @blur=&quot;onBlur&quot; /\\&gt; \\&lt;p\\&gt;Counter: \\{\\{ vueState.counter \\}\\}\\&lt;/p\\&gt;</code>, setup() { const onInput = (v: string) =&gt; { core.parseInput(v); sync() } const onBlur = () =&gt; { core.commit(); sync() } return { vueState, onInput, onBlur } } } createApp(App).mount(&#39;#app&#39;) &lt;img src=&quot;<a href="https://i.imgur.com/f2vNYnC.gif" target="_blank" rel="noreferrer">https://i.imgur.com/f2vNYnC.gif</a>&quot; width=&quot;390&quot; /&gt; <strong>效果</strong>：</p><ul><li>每次输入立刻打印</li><li>失焦后被格式化为 123.00 并打印</li><li>Counter 增加</li></ul><p><strong>4. 关键点 &amp; 深拷贝疑问</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>疑问</strong></td><td><strong>解释</strong></td></tr><tr><td><strong>reactive({ …core.state }) 是浅拷贝，errors 数组怎么办？</strong></td><td>在 sync() 里</td></tr><tr><td>vueState.errors = [...core.state.errors]</td><td></td></tr><tr><td>重新分配新数组 → setter 始终触发 → 避免引用共享。</td><td></td></tr><tr><td><strong>能不能直接 Object.assign？</strong></td><td>可以，但务必保证 Core 与 Proxy <strong>不是同一对象</strong>，并确保新旧值不同才能触发。</td></tr><tr><td><strong>为什么 Core 不能直接用 Proxy？</strong></td><td>Core 要保持 “框架无关” 及 <strong>可单元测试</strong>；把逻辑与 Vue Proxy 混在一起会让其它框架（React/Vue2/纯 JS）无法复用。</td></tr></tbody></table><p><strong>TL;DR</strong></p><ol><li><strong>Vue 响应式 = 依赖 Proxy setter</strong>。</li><li>Core 改原始对象 → Vue 不知道。</li><li>用「<strong>镜像 reactive 对象 + 每次写回 setter</strong>」就能两全其美。</li></ol></div>',1)])])}const m=e(s,[["render",n]]);export{l as __pageData,m as default};
